package com.crms.controller;import com.crms.entity.Company;import com.crms.repository.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.core.Authentication;import java.util.*;@RestController @RequestMapping("/api/companies") public class CompanyController{private final CompanyRepository companies;private final UserRepository users;public CompanyController(CompanyRepository c,UserRepository u){companies=c;users=u;}@GetMapping public List<Company> all(){return companies.findAll();}@GetMapping("/{id}")public Company get(@PathVariable Long id){return companies.findById(id).orElseThrow();}@GetMapping("/me")public Company me(Authentication a){return companies.findByOwnerId(users.findByEmailIgnoreCase(a.getName()).orElseThrow().getId()).orElseThrow();}@PutMapping("/me")public Company update(@RequestBody Company in,Authentication a){var c=me(a);c.setName(in.getName());c.setDescription(in.getDescription());c.setWebsite(in.getWebsite());c.setIndustry(in.getIndustry());return companies.save(c);}}
